def reach_gap(coords_, center, grid, maxd=2, include_diag=False):
 blocked={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2}
 pts={(center[0]+dy,center[1]+dx) for dy,dx in coords_ if 0<=center[0]+dy<11 and 0<=center[1]+dx<11 and (center[0]+dy,center[1]+dx) not in blocked}
 seen={center} if center in pts else set(); stack=list(seen)
 while stack:
  r,c=stack.pop()
  for rr,cc in pts-seen:
